inserted AS (
    INSERT INTO products (name, description, category_id, price, currency, discount_percentage, rating, unit, status)
    SELECT d.name, d.description, c.id, d.price, 'USD', d.discount_percentage, d.rating, d.unit, 'ACTIVE'
    FROM demo d
    JOIN categories c ON c.slug = d.category_slug
    RETURNING id, name, category_id
)
INSERT INTO product_variants (product_id, size, sku, stock, price_override)
SELECT
    i.id,
    s.size,
    'DEMO-' || UPPER(d.category_slug) || '-' || LPAD(d.seq::text, 2, '0') || '-'
        || UPPER(REGEXP_REPLACE(s.size, '[^A-Za-z0-9]', '', 'g')),
    -- Deterministic spread of stock levels, with the odd size sold out so that state shows up too.
    CASE WHEN (d.seq + s.ord) % 13 = 0 THEN 0 ELSE (d.seq * 7 + s.ord * 11 + LENGTH(d.category_slug)) % 37 + 3 END,
    -- The largest size of some tops and trousers costs a little more.
    CASE WHEN d.upcharge > 0 AND s.ord = CARDINALITY(d.sizes) THEN d.price + d.upcharge END
FROM inserted i
JOIN categories c ON c.id = i.category_id
JOIN demo d ON d.category_slug = c.slug AND d.name = i.name
CROSS JOIN LATERAL UNNEST(d.sizes) WITH ORDINALITY AS s (size, ord);

-- A renamed slug would silently drop a category's products from the join above. Fail instead.
DO $$
BEGIN
    IF (SELECT COUNT(DISTINCT product_id) FROM product_variants WHERE sku LIKE 'DEMO-%') <> 190 THEN
        RAISE EXCEPTION 'Demo seed expected 190 products; check the category slugs from V3';
    END IF;
END $$;
